// ── Configuration ──────────────────────────────────────────────
const N8N_BASE_URL = 'https://n8n.example.com'; // no trailing slash

// List the workflows to watch. Find a workflow's id in its URL: /workflow/<id>
const WORKFLOWS = [
  { workflowId: '123', workflowName: 'Hourly Data Sync', maxAgeHours: 2 },
  { workflowId: '456', workflowName: 'Nightly Backup', maxAgeHours: 26 },
];
// ───────────────────────────────────────────────────────────────

return WORKFLOWS.map((w) => ({
  json: { ...w, N8N_BASE_URL },
}));

// For each monitored workflow, compare its last successful run to the threshold.
// Only stale workflows are emitted (one item each) -> alerts fire only when needed.
const cfgItems = $('Monitored Workflows').all();
const inputs = $input.all();
const out = [];

for (let i = 0; i < inputs.length; i++) {
  const cfg = cfgItems[i]?.json ?? {};
  const data = inputs[i].json.data || [];
  const latest = data[0];
  const maxAgeHours = cfg.maxAgeHours ?? 24;
  const name = cfg.workflowName ?? 'Unknown workflow';

  let stale = false;
  let ageHours = null;
  let lastSuccess = 'never';

  if (!latest) {
    stale = true; // no successful execution on record
  } else {
    lastSuccess = latest.startedAt || latest.stoppedAt;
    ageHours = (Date.now() - new Date(lastSuccess).getTime()) / 3_600_000;
    stale = ageHours > maxAgeHours;
  }

  if (stale) {
    out.push({
      json: {
        workflowName: name,
        workflowId: cfg.workflowId,
        maxAgeHours,
        ageHours: ageHours === null ? null : Math.round(ageHours * 10) / 10,
        lastSuccess,
      },
    });
  }
}

return out;

